import { PrismaClient } from '@prisma/client';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { AppError } from '../middleware/error-handler';

const prisma = new PrismaClient();

export class AuthService {
  async register(email: string, name: string, password: string) {
    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) throw new AppError('Bu email zaten kayitli', 409);

    const hashedPassword = await bcrypt.hash(password, 12);
    const user = await prisma.user.create({
      data: { email, name, password: hashedPassword },
      select: { id: true, email: true, name: true, role: true },
    });

    const token = this.generateToken(user.id, user.role);
    return { user, accessToken: token };
  }

  async login(email: string, password: string) {
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) throw new AppError('Gecersiz email veya sifre', 401);

    const isValid = await bcrypt.compare(password, user.password);
    if (!isValid) throw new AppError('Gecersiz email veya sifre', 401);

    const token = this.generateToken(user.id, user.role);
    return { user: { id: user.id, email: user.email, name: user.name, role: user.role }, accessToken: token };
  }

  private generateToken(userId: string, role: string): string {
    return jwt.sign({ userId, role }, process.env.JWT_SECRET!, { expiresIn: '7d' });
  }
}

import { Router } from 'express';
import { AuthService } from '../services/auth.service';

