// src/services/payment.service.ts
import Stripe from 'stripe';
import { PrismaClient } from '@prisma/client';
import { CartService } from './cart.service';
import { AppError } from '../middleware/error-handler';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2025-12-18.acacia',
});
const prisma = new PrismaClient();
const cartService = new CartService();

export class PaymentService {
  async createCheckoutSession(userId: string, shippingAddress: string) {
    const cartItems = await cartService.getCart(userId);

    if (cartItems.length === 0) {
      throw new AppError('Sepetiniz boş', 400);
    }

    // Stok kontrolü
    for (const item of cartItems) {
      const product = await prisma.product.findUnique({
        where: { id: item.productId },
      });
      if (!product || product.stock < item.quantity) {
        throw new AppError(`${item.name} için yeterli stok yok`, 400);
      }
    }

    // Sipariş oluştur (PENDING durumunda)
    const totalAmount = cartItems.reduce(
      (sum, item) => sum + item.price * item.quantity,
      0
    );

    const order = await prisma.order.create({
      data: {
        userId,
        totalAmount,
        shippingAddress,
        status: 'PENDING',
        items: {
          create: cartItems.map((item) => ({
            productId: item.productId,
            quantity: item.quantity,
            unitPrice: item.price,
          })),
        },
      },
      include: { items: true },
    });

    // Stripe Checkout Session
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      mode: 'payment',
      client_reference_id: order.id,
      customer_email: (await prisma.user.findUnique({ where: { id: userId } }))?.email,
      line_items: cartItems.map((item) => ({
        price_data: {
          currency: 'try',
          product_data: {
            name: item.name,
            images: item.image ? [item.image] : [],
          },
          unit_amount: Math.round(item.price * 100), // kuruş cinsinden
        },
        quantity: item.quantity,
      })),
      success_url: `${process.env.CLIENT_URL}/orders/${order.id}?success=true`,
      cancel_url: `${process.env.CLIENT_URL}/cart?cancelled=true`,
      metadata: { orderId: order.id },
    });

    // Sipariş'e Stripe session ID'yi kaydet
    await prisma.order.update({
      where: { id: order.id },
      data: { stripeSessionId: session.id },
    });

    return { sessionUrl: session.url, orderId: order.id };
  }
}

