import axios from 'axios';

const FRAUD_SERVICE_URL = process.env.FRAUD_SERVICE_URL || 'http://localhost:5000';

interface FraudResult {
  fraud_score: number;
  is_suspicious: boolean;
  risk_level: 'low' | 'medium' | 'high';
}

export class FraudService {
  async analyzeOrder(orderData: {
    orderAmount: number;
    itemsCount: number;
    isNewCustomer: boolean;
    shippingBillingMatch: boolean;
    previousOrders: number;
  }): Promise<FraudResult> {
    try {
      const { data } = await axios.post(`${FRAUD_SERVICE_URL}/predict`, {
        order_amount: orderData.orderAmount,
        items_count: orderData.itemsCount,
        hour_of_day: new Date().getHours(),
        is_new_customer: orderData.isNewCustomer ? 1 : 0,
        shipping_billing_match: orderData.shippingBillingMatch ? 1 : 0,
        previous_orders: orderData.previousOrders,
      });

